-- Seed for public.glossary_terms — 300 finance terms across 15 categories.
-- Idempotent: re-paste this file in Supabase Studio to apply edits.

insert into public.glossary_terms
  (slug, term, definition, extended_definition, category, difficulty, related_slugs, examples)
values
-- =================================================================
-- Investing basics (20)
-- =================================================================
('asset-class', 'Asset class', 'A group of investments with similar characteristics, like stocks, bonds, cash, or real estate.', 'Asset classes behave differently in various market conditions, which is why diversification across them helps manage risk. The major classes are equities, fixed income, cash equivalents, real estate, and commodities.', 'Investing basics', 'Basic', '{diversification,portfolio,asset-allocation}', '[]'::jsonb),
('asset-allocation', 'Asset allocation', 'The strategy of dividing a portfolio across asset classes to balance risk and reward.', 'A typical mix might be 60% stocks and 40% bonds, but the right allocation depends on time horizon, goals, and risk tolerance. Many investors rebalance periodically to maintain target weights.', 'Investing basics', 'Basic', '{asset-class,rebalancing,risk-tolerance,diversification}', '[{"title":"60/40 portfolio","body":"A classic balanced allocation holds 60% in equities for growth and 40% in bonds for stability."}]'::jsonb),
('compounding', 'Compounding', 'The process where earnings generate further earnings over time.', 'Compounding is why starting to invest early matters so much: returns reinvested today produce their own returns tomorrow. Over decades, the effect dwarfs the original contributions.', 'Investing basics', 'Basic', '{compound-annual-growth-rate,return,principal}', '[{"title":"The power of time","body":"$10,000 at 7% annual returns becomes ~$76,000 in 30 years without adding a dollar."}]'::jsonb),
('dividend', 'Dividend', 'A cash or stock payment a company distributes to shareholders out of its profits.', 'Dividends are typically paid quarterly and are a way mature, cash-generating companies return capital to investors. Not all companies pay them — many reinvest profits into growth instead.', 'Investing basics', 'Beginner', '{dividend-yield,payout-ratio,ex-dividend-date,qualified-dividend}', '[]'::jsonb),
('liquidity', 'Liquidity', 'How quickly an asset can be converted to cash without affecting its price.', 'Cash is perfectly liquid; large-cap stocks are highly liquid; real estate and private equity are illiquid. Liquidity matters because illiquid assets can be hard to sell during downturns.', 'Investing basics', 'Beginner', '{bid-ask-spread,market-maker,float}', '[]'::jsonb),
('risk-tolerance', 'Risk tolerance', 'An investor''s emotional and financial ability to withstand portfolio losses.', 'Risk tolerance combines how much volatility you can stomach with how much you can afford to lose given your time horizon and obligations. It shapes appropriate asset allocation.', 'Investing basics', 'Beginner', '{asset-allocation,time-horizon,diversification}', '[]'::jsonb),
('portfolio', 'Portfolio', 'The full collection of investments owned by an individual or institution.', 'A portfolio''s composition — across asset classes, sectors, and geographies — drives most of its long-term return and risk profile.', 'Investing basics', 'Basic', '{diversification,asset-allocation,rebalancing}', '[]'::jsonb),
('yield', 'Yield', 'The income an investment generates, expressed as a percentage of its price.', 'For bonds, yield is interest income; for stocks, it''s dividend income. Yield is one component of total return, alongside price appreciation.', 'Investing basics', 'Beginner', '{dividend-yield,yield-to-maturity,coupon}', '[]'::jsonb),
('capital-gain', 'Capital gain', 'The profit realized when an asset is sold above its purchase price.', 'Capital gains are taxed differently depending on how long the asset was held — short-term gains (under a year) are taxed as ordinary income, long-term gains at lower rates.', 'Investing basics', 'Beginner', '{long-term-capital-gain,short-term-capital-gain,capital-gains-tax}', '[]'::jsonb),
('capital-loss', 'Capital loss', 'The loss realized when an asset is sold below its purchase price.', 'Capital losses can offset capital gains for tax purposes, and up to $3,000 of net losses can offset ordinary income each year, with the remainder carried forward.', 'Investing basics', 'Beginner', '{tax-loss-harvesting,wash-sale-rule,capital-gain}', '[]'::jsonb),
('principal', 'Principal', 'The original amount of money invested or borrowed, before any returns or interest.', 'In a bond, principal is the face value repaid at maturity. In a loan, it''s the amount borrowed, separate from interest charges.', 'Investing basics', 'Basic', '{face-value,return,compounding}', '[]'::jsonb),
('return', 'Return', 'The gain or loss on an investment over a period, usually expressed as a percentage.', 'Total return includes both income (dividends, interest) and price appreciation. Comparing returns to a relevant benchmark gives context.', 'Investing basics', 'Basic', '{alpha,benchmark-index,compound-annual-growth-rate}', '[]'::jsonb),
('nominal-return', 'Nominal return', 'The raw return on an investment before adjusting for inflation.', 'Nominal return looks higher than reality during inflationary periods. Real return — nominal minus inflation — reflects actual purchasing-power growth.', 'Investing basics', 'Intermediate', '{real-return,inflation,inflation-adjusted-return}', '[]'::jsonb),
('real-return', 'Real return', 'Investment return adjusted for inflation, reflecting true purchasing-power growth.', 'If a portfolio returns 7% nominally and inflation is 3%, the real return is roughly 4%. Real return is what matters for long-term goals like retirement.', 'Investing basics', 'Intermediate', '{nominal-return,inflation,inflation-adjusted-return}', '[]'::jsonb),
('inflation-adjusted-return', 'Inflation-adjusted return', 'Another name for real return — the return remaining after inflation is subtracted.', 'Investors comparing investments across time periods with different inflation rates should always use inflation-adjusted figures.', 'Investing basics', 'Intermediate', '{real-return,nominal-return,inflation}', '[]'::jsonb),
('time-horizon', 'Time horizon', 'How long an investor expects to hold an investment before needing the funds.', 'Longer horizons allow more risk-taking because there''s time to recover from drawdowns. Short horizons demand capital preservation.', 'Investing basics', 'Basic', '{risk-tolerance,asset-allocation,buy-and-hold}', '[]'::jsonb),
('dollar-cost-averaging', 'Dollar-cost averaging', 'Investing a fixed amount on a regular schedule regardless of price.', 'DCA reduces the risk of investing a lump sum at a market peak and is the default approach for retirement contributions. Over very long periods, lump-sum investing usually outperforms it.', 'Investing basics', 'Beginner', '{lump-sum-investing,buy-and-hold,time-horizon}', '[{"title":"401(k) example","body":"Contributing $500 every payday is dollar-cost averaging — you buy more shares when prices are low and fewer when prices are high."}]'::jsonb),
('lump-sum-investing', 'Lump-sum investing', 'Putting a large amount of capital into the market all at once.', 'Historically, lump-sum investing beats dollar-cost averaging about two-thirds of the time because markets rise more often than they fall — but it carries higher short-term timing risk.', 'Investing basics', 'Intermediate', '{dollar-cost-averaging,time-horizon}', '[]'::jsonb),
('buy-and-hold', 'Buy and hold', 'A long-term strategy of holding investments through market cycles instead of trading actively.', 'Buy and hold avoids transaction costs, taxes on short-term gains, and the difficulty of market timing. It''s the strategy behind most index investing.', 'Investing basics', 'Basic', '{time-horizon,index-fund,dollar-cost-averaging}', '[]'::jsonb),
('rebalancing', 'Rebalancing', 'Adjusting a portfolio back to its target asset allocation after drift.', 'If stocks rally, they grow as a share of the portfolio above their target weight; rebalancing trims stocks and buys bonds to restore balance, enforcing a "sell high, buy low" discipline.', 'Investing basics', 'Beginner', '{asset-allocation,portfolio,diversification}', '[]'::jsonb),
('compound-annual-growth-rate', 'Compound annual growth rate (CAGR)', 'The constant annual rate that would grow a starting value to an ending value over a period.', 'CAGR smooths out volatile year-to-year returns into a single comparable figure. It''s widely used to compare investments across different timeframes.', 'Investing basics', 'Intermediate', '{compounding,return,nominal-return}', '[]'::jsonb),
('benchmark-index', 'Benchmark index', 'A standard index against which an investment''s performance is compared.', 'The S&P 500 is the default benchmark for U.S. large-cap funds; the Russell 2000 for small-caps. Choosing the right benchmark matters — comparing a small-cap fund to the S&P 500 is misleading.', 'Investing basics', 'Beginner', '{return,alpha,tracking-error,index-fund}', '[]'::jsonb),

-- =================================================================
-- Stocks & equities (25)
-- =================================================================
('common-stock', 'Common stock', 'Ownership shares in a company that typically come with voting rights and variable dividends.', 'Common shareholders are last in line during bankruptcy — behind bondholders and preferred shareholders — but capture all the upside if the company succeeds.', 'Stocks & equities', 'Basic', '{preferred-stock,equity,shareholder,voting-rights}', '[]'::jsonb),
('preferred-stock', 'Preferred stock', 'A class of stock with fixed dividends and priority over common stock in liquidation.', 'Preferred shares behave somewhat like bonds — stable income, less price appreciation — and usually lack voting rights.', 'Stocks & equities', 'Intermediate', '{common-stock,equity,share-class,dividend}', '[]'::jsonb),
('float', 'Float', 'The number of shares actually available for public trading.', 'Float excludes insider, restricted, and treasury shares. Low-float stocks tend to be more volatile because relatively small order flows move the price.', 'Stocks & equities', 'Intermediate', '{outstanding-shares,authorized-shares,liquidity}', '[]'::jsonb),
('market-capitalization', 'Market capitalization', 'The total dollar value of a company''s outstanding shares (price × shares outstanding).', 'Market cap is the standard size metric used to classify stocks as small-, mid-, large-, or mega-cap. It reflects what the market currently thinks the equity is worth.', 'Stocks & equities', 'Basic', '{small-cap,mid-cap,large-cap,outstanding-shares}', '[{"title":"Calculation","body":"A company with 100M shares trading at $50 has a market cap of $5B."}]'::jsonb),
('stock-split', 'Stock split', 'A corporate action that increases share count while proportionally lowering the price.', 'A 2-for-1 split doubles shares outstanding and halves the price — total value held by each investor is unchanged. Companies split to keep share prices in retail-friendly ranges.', 'Stocks & equities', 'Beginner', '{reverse-stock-split,share-buyback,outstanding-shares}', '[]'::jsonb),
('reverse-stock-split', 'Reverse stock split', 'A corporate action that consolidates shares, raising the per-share price.', 'A 1-for-10 reverse split turns ten $1 shares into one $10 share. Often used to avoid delisting after a stock price has fallen below an exchange minimum.', 'Stocks & equities', 'Intermediate', '{stock-split,delisting}', '[]'::jsonb),
('share-class', 'Share class', 'A category of stock with distinct voting or economic rights.', 'Tech companies often issue Class A shares (one vote) and Class B (ten votes, held by founders) so insiders keep control after going public.', 'Stocks & equities', 'Intermediate', '{voting-rights,common-stock,preferred-stock}', '[]'::jsonb),
('voting-rights', 'Voting rights', 'A shareholder''s ability to vote on corporate matters like board elections and major decisions.', 'Most common stock carries one vote per share. Dual-class structures concentrate voting power in founders'' hands.', 'Stocks & equities', 'Basic', '{share-class,proxy-vote,common-stock}', '[]'::jsonb),
('equity', 'Equity', 'Ownership in an asset after debts against it are paid; for companies, total assets minus liabilities.', 'On a balance sheet, equity equals what would be left for shareholders if all assets were sold and all debts settled. Also used loosely to mean "stocks."', 'Stocks & equities', 'Basic', '{shareholder,common-stock,balance-sheet,retained-earnings}', '[]'::jsonb),
('shareholder', 'Shareholder', 'A person or entity that owns shares of a company.', 'Shareholders share in the company''s success through dividends and price appreciation, and may vote on certain corporate matters.', 'Stocks & equities', 'Basic', '{common-stock,voting-rights,equity}', '[]'::jsonb),
('blue-chip-stock', 'Blue-chip stock', 'Shares of large, well-established companies with reliable earnings and dividends.', 'Blue chips are typically Dow components or S&P 500 stalwarts — household names with decades of operating history. Considered relatively lower risk within equities.', 'Stocks & equities', 'Beginner', '{large-cap,dividend,common-stock}', '[]'::jsonb),
('growth-stock', 'Growth stock', 'A stock expected to grow earnings faster than the broader market.', 'Growth companies usually reinvest profits instead of paying dividends, trade at higher valuation multiples, and concentrate in tech and biotech.', 'Stocks & equities', 'Beginner', '{value-stock,price-to-earnings-ratio,peg-ratio}', '[]'::jsonb),
('value-stock', 'Value stock', 'A stock trading at a low price relative to fundamentals like earnings or book value.', 'Value investing seeks stocks the market has undervalued. Classic value sectors include financials, energy, and industrials.', 'Stocks & equities', 'Beginner', '{growth-stock,price-to-book-ratio,price-to-earnings-ratio}', '[]'::jsonb),
('small-cap', 'Small-cap', 'A company with a market capitalization roughly between $300M and $2B.', 'Small-caps tend to be more volatile but historically offer higher long-term returns than large-caps as compensation for that risk.', 'Stocks & equities', 'Intermediate', '{market-capitalization,mid-cap,micro-cap}', '[]'::jsonb),
('mid-cap', 'Mid-cap', 'A company with a market capitalization roughly between $2B and $10B.', 'Mid-caps are often past startup risk but still in their growth phase, balancing potential with relative stability.', 'Stocks & equities', 'Intermediate', '{market-capitalization,small-cap,large-cap}', '[]'::jsonb),
('large-cap', 'Large-cap', 'A company with a market capitalization above roughly $10B.', 'Large-caps dominate major indices like the S&P 500 and tend to have global operations, stable cash flows, and more analyst coverage.', 'Stocks & equities', 'Basic', '{market-capitalization,blue-chip-stock,mid-cap}', '[]'::jsonb),
('micro-cap', 'Micro-cap', 'A company with a market capitalization roughly between $50M and $300M.', 'Micro-caps trade thinly, attract less analyst coverage, and carry higher business risk. They can deliver outsized returns or large losses.', 'Stocks & equities', 'Advanced', '{market-capitalization,small-cap,penny-stock}', '[]'::jsonb),
('penny-stock', 'Penny stock', 'A stock trading under $5 per share, often with small market cap and low liquidity.', 'Penny stocks are notorious for pump-and-dump schemes and trade on the OTC markets rather than major exchanges.', 'Stocks & equities', 'Advanced', '{micro-cap,liquidity}', '[]'::jsonb),
('ipo', 'IPO (Initial Public Offering)', 'A private company''s first sale of shares to the public.', 'IPOs let companies raise capital and give insiders a path to liquidity. Newly public stocks often see high volatility as the float widens and lockup periods expire.', 'Stocks & equities', 'Beginner', '{secondary-offering,lockup-period,float}', '[]'::jsonb),
('secondary-offering', 'Secondary offering', 'An issuance of additional shares by an already-public company.', 'Secondary offerings dilute existing shareholders but raise fresh capital. They often press the stock price lower in the short term.', 'Stocks & equities', 'Intermediate', '{ipo,outstanding-shares,authorized-shares}', '[]'::jsonb),
('lockup-period', 'Lockup period', 'A post-IPO window — typically 90 to 180 days — when insiders cannot sell shares.', 'Lockup expirations often pressure the share price as a wave of insider selling hits the market.', 'Stocks & equities', 'Intermediate', '{ipo,float}', '[]'::jsonb),
('share-buyback', 'Share buyback', 'A company repurchasing its own shares from the open market.', 'Buybacks reduce share count, boosting EPS and often the stock price. They''re an alternative to dividends for returning capital to shareholders.', 'Stocks & equities', 'Intermediate', '{treasury-stock,eps,dividend,outstanding-shares}', '[]'::jsonb),
('treasury-stock', 'Treasury stock', 'Shares the company has repurchased and is holding rather than retiring.', 'Treasury shares don''t vote, don''t receive dividends, and aren''t part of EPS calculations. They can be reissued later.', 'Stocks & equities', 'Intermediate', '{share-buyback,outstanding-shares,authorized-shares}', '[]'::jsonb),
('authorized-shares', 'Authorized shares', 'The maximum number of shares a company''s charter permits it to issue.', 'Authorized shares are an upper bound, not all of which are necessarily issued. Increasing the cap requires a shareholder vote.', 'Stocks & equities', 'Intermediate', '{outstanding-shares,treasury-stock,float}', '[]'::jsonb),
('outstanding-shares', 'Outstanding shares', 'The total shares currently held by all investors, including insiders and the public.', 'Outstanding shares are used to compute market cap and EPS. Outstanding equals issued shares minus treasury shares.', 'Stocks & equities', 'Beginner', '{authorized-shares,float,treasury-stock,market-capitalization}', '[]'::jsonb),

-- =================================================================
-- Bonds & fixed income (25)
-- =================================================================
('bond', 'Bond', 'A debt security where an investor loans money to an issuer in exchange for periodic interest and principal repayment at maturity.', 'Bonds are the foundation of fixed-income investing. Their prices move inversely to interest rates.', 'Bonds & fixed income', 'Basic', '{coupon,face-value,maturity,yield-to-maturity}', '[]'::jsonb),
('coupon', 'Coupon', 'The periodic interest payment a bond makes to its holder, expressed as a percent of face value.', 'A 5% coupon on a $1,000 face-value bond pays $50 per year, usually split into semi-annual payments.', 'Bonds & fixed income', 'Beginner', '{bond,face-value,yield,accrued-interest}', '[]'::jsonb),
('face-value', 'Face value', 'The amount a bond will pay back at maturity, also called par value.', 'Most corporate and government bonds have a face value of $1,000. Market price can trade above or below par based on interest rates and credit risk.', 'Bonds & fixed income', 'Beginner', '{par-value,bond,maturity,coupon}', '[]'::jsonb),
('maturity', 'Maturity', 'The date on which a bond''s principal is repaid to the holder.', 'Bonds are classified by maturity as short-term (under 3 years), intermediate (3 to 10), or long-term (over 10).', 'Bonds & fixed income', 'Beginner', '{bond,duration,face-value,yield-to-maturity}', '[]'::jsonb),
('yield-to-maturity', 'Yield to maturity', 'The total annualized return an investor earns if a bond is held to maturity.', 'YTM accounts for coupon payments, the bond''s current price, and any premium or discount to par. It''s the standard way to compare bonds.', 'Bonds & fixed income', 'Intermediate', '{yield,coupon,maturity,bond}', '[]'::jsonb),
('duration', 'Duration', 'A measure of how sensitive a bond''s price is to changes in interest rates.', 'A bond with duration of 7 will roughly lose 7% of its price for every 1% rise in rates. Longer-maturity bonds generally have higher duration.', 'Bonds & fixed income', 'Intermediate', '{convexity,bond,maturity,yield-curve}', '[]'::jsonb),
('convexity', 'Convexity', 'A second-order measure of how a bond''s duration changes as interest rates move.', 'Convexity captures the curvature of the bond price/yield relationship. High convexity is desirable — prices rise more on rate cuts than they fall on equal rate hikes.', 'Bonds & fixed income', 'Advanced', '{duration,bond,yield-curve}', '[]'::jsonb),
('yield-curve', 'Yield curve', 'A plot of bond yields across different maturities for the same issuer, typically the Treasury.', 'A normal curve slopes upward (longer = higher yield). An inverted curve, where short rates exceed long rates, has historically preceded recessions.', 'Bonds & fixed income', 'Intermediate', '{treasury-bond,treasury-note,treasury-bill,recession}', '[]'::jsonb),
('credit-spread', 'Credit spread', 'The yield difference between a corporate bond and a Treasury of the same maturity.', 'Wider spreads indicate the market sees higher credit risk; narrowing spreads suggest improving conditions.', 'Bonds & fixed income', 'Intermediate', '{credit-rating,investment-grade,high-yield-bond,treasury-bond}', '[]'::jsonb),
('credit-rating', 'Credit rating', 'An independent assessment of an issuer''s ability to repay debt.', 'Agencies like S&P, Moody''s, and Fitch issue ratings from AAA (highest) down to D (default). Investment-grade starts at BBB- / Baa3.', 'Bonds & fixed income', 'Beginner', '{investment-grade,high-yield-bond,corporate-bond,credit-spread}', '[]'::jsonb),
('investment-grade', 'Investment grade', 'A credit rating of BBB-/Baa3 or higher, signaling relatively low default risk.', 'Many institutional investors are restricted by mandate to investment-grade bonds only. Falling below this threshold (a "fallen angel") often forces selling.', 'Bonds & fixed income', 'Intermediate', '{credit-rating,high-yield-bond,corporate-bond}', '[]'::jsonb),
('high-yield-bond', 'High-yield bond', 'A bond rated below investment grade, offering higher yields to compensate for higher default risk.', 'Also called speculative-grade or junk bonds. Often issued by leveraged companies or in private equity buyouts.', 'Bonds & fixed income', 'Intermediate', '{junk-bond,credit-rating,investment-grade,credit-spread}', '[]'::jsonb),
('junk-bond', 'Junk bond', 'Informal term for a high-yield, below-investment-grade bond.', 'The "junk" label captures the elevated default risk. Returns can rival equities in good years and decline sharply in stressed credit markets.', 'Bonds & fixed income', 'Intermediate', '{high-yield-bond,credit-rating}', '[]'::jsonb),
('treasury-bond', 'Treasury bond', 'A long-term U.S. government debt security with maturity of 20 or 30 years.', 'T-bonds are considered virtually risk-free in nominal terms because they''re backed by the full faith and credit of the U.S. government.', 'Bonds & fixed income', 'Basic', '{treasury-note,treasury-bill,yield-curve,bond}', '[]'::jsonb),
('treasury-note', 'Treasury note', 'A U.S. government debt security with a maturity of 2 to 10 years.', 'The 10-year Treasury note is one of the most-watched bonds in global markets — its yield serves as a benchmark for mortgages and corporate borrowing.', 'Bonds & fixed income', 'Basic', '{treasury-bond,treasury-bill,yield-curve}', '[]'::jsonb),
('treasury-bill', 'Treasury bill', 'A short-term U.S. government debt security with maturity of one year or less.', 'T-bills are sold at a discount to face value and pay no coupon — the return is the difference between purchase price and par.', 'Bonds & fixed income', 'Basic', '{treasury-note,treasury-bond,zero-coupon-bond}', '[]'::jsonb),
('tips', 'TIPS (Treasury Inflation-Protected Securities)', 'U.S. Treasuries whose principal adjusts with inflation.', 'TIPS protect real purchasing power. The coupon rate is fixed but applies to a principal that grows with CPI, so both interest and principal at maturity rise with inflation.', 'Bonds & fixed income', 'Intermediate', '{inflation,consumer-price-index,treasury-bond,real-return}', '[]'::jsonb),
('municipal-bond', 'Municipal bond', 'A bond issued by a state or local government, often with tax-exempt interest.', 'Muni interest is generally exempt from federal income tax and may be exempt from state taxes for in-state residents. Popular with high-bracket investors.', 'Bonds & fixed income', 'Intermediate', '{bond,corporate-bond,treasury-bond,capital-gains-tax}', '[]'::jsonb),
('corporate-bond', 'Corporate bond', 'A debt security issued by a company to raise capital.', 'Corporate bonds carry credit risk that Treasuries do not, and they pay higher yields to compensate. Quality ranges from investment-grade to deep junk.', 'Bonds & fixed income', 'Beginner', '{bond,credit-rating,investment-grade,high-yield-bond}', '[]'::jsonb),
('zero-coupon-bond', 'Zero-coupon bond', 'A bond that pays no periodic interest, sold at a deep discount to face value.', 'The return is the difference between purchase price and the face value paid at maturity. Treasury STRIPS and T-bills are zero-coupon instruments.', 'Bonds & fixed income', 'Intermediate', '{bond,treasury-bill,face-value,duration}', '[]'::jsonb),
('callable-bond', 'Callable bond', 'A bond the issuer can redeem before maturity at a predetermined price.', 'Issuers call bonds when rates fall, refinancing into cheaper debt. This caps upside for investors, so callable bonds typically yield more than comparable non-callable issues.', 'Bonds & fixed income', 'Intermediate', '{bond,maturity,corporate-bond}', '[]'::jsonb),
('convertible-bond', 'Convertible bond', 'A corporate bond that can be exchanged for a fixed number of shares.', 'Convertibles act like bonds when the stock is weak and like equity when it rallies. They appeal to investors wanting upside with downside protection.', 'Bonds & fixed income', 'Advanced', '{bond,corporate-bond,equity,common-stock}', '[]'::jsonb),
('par-value', 'Par value', 'Another name for face value — the amount a bond returns at maturity.', 'A bond trading at par means market price equals face value; "above par" or "below par" describes premium and discount pricing.', 'Bonds & fixed income', 'Beginner', '{face-value,bond,coupon}', '[]'::jsonb),
('accrued-interest', 'Accrued interest', 'Interest that has built up on a bond between coupon payments but not yet paid.', 'When you buy a bond between coupon dates, you pay the seller for accrued interest, then receive the full next coupon.', 'Bonds & fixed income', 'Intermediate', '{coupon,bond}', '[]'::jsonb),
('bond-ladder', 'Bond ladder', 'A portfolio of bonds with staggered maturities, so a portion matures each year.', 'Laddering reduces reinvestment risk by spreading rate exposure across the curve and provides steady, predictable cash flows.', 'Bonds & fixed income', 'Intermediate', '{bond,maturity,yield-curve}', '[]'::jsonb),

-- =================================================================
-- Market structure & order types (20)
-- =================================================================
('limit-order', 'Limit order', 'An order to buy or sell at a specific price or better.', 'Limit orders give price certainty but no fill guarantee — if the market never reaches the limit, the order doesn''t execute.', 'Market structure & order types', 'Beginner', '{market-order,stop-loss-order,stop-limit-order}', '[]'::jsonb),
('market-order', 'Market order', 'An order to buy or sell immediately at the best available price.', 'Market orders prioritize speed and certainty of execution over price. They can suffer slippage in fast-moving or thinly-traded names.', 'Market structure & order types', 'Beginner', '{limit-order,bid-ask-spread,liquidity}', '[]'::jsonb),
('stop-loss-order', 'Stop-loss order', 'An order that triggers a market sale when a stock falls to a specified price.', 'Stop-losses limit downside but can be triggered by brief intraday spikes, locking in losses just before a rebound.', 'Market structure & order types', 'Beginner', '{stop-limit-order,trailing-stop,limit-order}', '[]'::jsonb),
('stop-limit-order', 'Stop-limit order', 'A stop order that converts to a limit order — rather than a market order — once triggered.', 'Combines protection of a stop with price control of a limit. The risk: no execution if the market gaps past the limit.', 'Market structure & order types', 'Intermediate', '{stop-loss-order,limit-order,trailing-stop}', '[]'::jsonb),
('trailing-stop', 'Trailing stop', 'A stop order whose trigger price follows the market as it moves in your favor.', 'On a long position, the stop ratchets up with the price and never down. It locks in gains while letting winners run.', 'Market structure & order types', 'Intermediate', '{stop-loss-order,stop-limit-order}', '[]'::jsonb),
('bid-ask-spread', 'Bid-ask spread', 'The difference between the highest price a buyer will pay and the lowest a seller will accept.', 'Narrow spreads indicate liquid markets; wide spreads mean higher transaction costs and less liquidity. Market makers profit from this spread.', 'Market structure & order types', 'Beginner', '{market-maker,liquidity,nbbo}', '[]'::jsonb),
('dark-pool', 'Dark pool', 'A private trading venue where large orders execute away from public exchanges.', 'Institutions use dark pools to move blocks without telegraphing intentions to the market. Critics argue they fragment liquidity and obscure price discovery.', 'Market structure & order types', 'Advanced', '{market-maker,high-frequency-trading,liquidity}', '[]'::jsonb),
('market-maker', 'Market maker', 'A firm that continuously quotes buy and sell prices for a security, providing liquidity.', 'Market makers earn the bid-ask spread in exchange for taking on inventory risk. They''re essential to functioning equity and options markets.', 'Market structure & order types', 'Intermediate', '{bid-ask-spread,liquidity,specialist,nbbo}', '[]'::jsonb),
('high-frequency-trading', 'High-frequency trading (HFT)', 'Algorithmic trading that uses sophisticated tech to execute orders in microseconds.', 'HFT firms profit from tiny price differences and rebates. They provide liquidity in normal markets but have been blamed for volatility during flash crashes.', 'Market structure & order types', 'Advanced', '{dark-pool,market-maker,payment-for-order-flow}', '[]'::jsonb),
('payment-for-order-flow', 'Payment for order flow (PFOF)', 'Compensation a broker receives for routing customer orders to a particular market maker.', 'PFOF lets retail brokers offer zero-commission trading, but raises questions about whether customers get the best execution.', 'Market structure & order types', 'Advanced', '{market-maker,high-frequency-trading,nbbo}', '[]'::jsonb),
('specialist', 'Specialist', 'A traditional NYSE designated market maker responsible for orderly trading in specific stocks.', 'Specialists have largely been replaced by Designated Market Makers (DMMs) in modern electronic trading, but the function — maintaining orderly markets — remains.', 'Market structure & order types', 'Advanced', '{market-maker,nbbo}', '[]'::jsonb),
('level-2-quote', 'Level 2 quote', 'A market data feed showing the full order book — bids and offers at multiple price levels.', 'Level 2 gives traders insight into supply and demand beyond the best bid/ask. Useful for short-term strategies and reading order flow.', 'Market structure & order types', 'Advanced', '{nbbo,bid-ask-spread,market-maker}', '[]'::jsonb),
('nbbo', 'National Best Bid and Offer (NBBO)', 'The best (highest) bid and best (lowest) offer across all U.S. exchanges for a security.', 'Brokers are required by Reg NMS to execute at the NBBO or better. The NBBO is the reference price for retail order routing.', 'Market structure & order types', 'Advanced', '{bid-ask-spread,market-maker,payment-for-order-flow}', '[]'::jsonb),
('settlement', 'Settlement', 'The transfer of cash and securities to complete a trade.', 'In U.S. equities, settlement moved from T+2 to T+1 in May 2024 — trades now settle one business day after execution.', 'Market structure & order types', 'Beginner', '{t-plus-2}', '[]'::jsonb),
('t-plus-2', 'T+2', 'A settlement convention where trades settle two business days after execution.', 'U.S. equities used T+2 until May 2024, when it shifted to T+1. Bonds and some other markets still use longer cycles.', 'Market structure & order types', 'Intermediate', '{settlement}', '[]'::jsonb),
('short-selling', 'Short selling', 'Borrowing a stock to sell it, hoping to repurchase later at a lower price.', 'Shorts profit from price declines but face theoretically unlimited losses if the stock rallies. Short squeezes amplify upside moves on heavily shorted names.', 'Market structure & order types', 'Advanced', '{naked-short-selling,covered-call}', '[]'::jsonb),
('naked-short-selling', 'Naked short selling', 'Selling shares short without first borrowing them.', 'Naked shorting is illegal in most jurisdictions because it can drive prices down without real shares backing the sale, creating settlement failures.', 'Market structure & order types', 'Advanced', '{short-selling,settlement}', '[]'::jsonb),
('circuit-breaker', 'Circuit breaker', 'Exchange rules that pause trading after sharp price moves to let the market reset.', 'U.S. equities have market-wide circuit breakers at 7%, 13%, and 20% S&P 500 drops, plus single-stock limits.', 'Market structure & order types', 'Intermediate', '{halt}', '[]'::jsonb),
('halt', 'Trading halt', 'A temporary suspension of trading in a security, typically pending news or after extreme volatility.', 'Halts give the market time to digest information so trading resumes in an orderly way. Common around earnings preannouncements, M&A leaks, and regulatory actions.', 'Market structure & order types', 'Intermediate', '{circuit-breaker}', '[]'::jsonb),
('arbitrage', 'Arbitrage', 'Simultaneously buying and selling an asset in different markets to profit from price differences.', 'True risk-free arbitrage is rare and short-lived — algorithmic traders close such gaps in milliseconds. Most strategies called "arbitrage" carry some residual risk.', 'Market structure & order types', 'Advanced', '{high-frequency-trading,market-maker}', '[]'::jsonb),

-- =================================================================
-- Financial statements (25)
-- =================================================================
('income-statement', 'Income statement', 'A financial statement showing revenue, expenses, and profit over a period.', 'Also called the P&L. Reads from top (revenue) to bottom (net income), with progressively more costs subtracted at each line.', 'Financial statements', 'Basic', '{revenue,net-income,gross-profit,operating-income,ebitda}', '[]'::jsonb),
('balance-sheet', 'Balance sheet', 'A snapshot of a company''s assets, liabilities, and equity at a single point in time.', 'The fundamental accounting identity: Assets = Liabilities + Equity. The balance sheet must always balance.', 'Financial statements', 'Basic', '{equity,goodwill,working-capital,retained-earnings}', '[]'::jsonb),
('cash-flow-statement', 'Cash flow statement', 'A statement breaking down cash inflows and outflows across operating, investing, and financing activities.', 'Reconciles net income to actual cash. Critical because earnings can be manipulated through accruals while cash is harder to fake.', 'Financial statements', 'Beginner', '{operating-cash-flow,free-cash-flow,capex}', '[]'::jsonb),
('statement-of-equity', 'Statement of stockholders'' equity', 'A statement detailing changes in equity over a period — earnings, dividends, buybacks, issuance.', 'Helps investors track exactly how equity moved between buybacks, dividends, share issuance, and retained earnings.', 'Financial statements', 'Intermediate', '{retained-earnings,equity,share-buyback,dividend}', '[]'::jsonb),
('revenue', 'Revenue', 'The total income a company earns from its primary business activities before any costs.', 'Also called the "top line" because it appears at the top of the income statement. Growing revenue is necessary but not sufficient for profitability.', 'Financial statements', 'Basic', '{income-statement,cost-of-goods-sold,gross-profit}', '[]'::jsonb),
('cost-of-goods-sold', 'Cost of goods sold (COGS)', 'The direct costs of producing goods or services sold during the period.', 'Includes raw materials, direct labor, and manufacturing overhead. Revenue minus COGS equals gross profit.', 'Financial statements', 'Beginner', '{gross-profit,gross-margin,revenue}', '[]'::jsonb),
('gross-profit', 'Gross profit', 'Revenue minus cost of goods sold — what''s left after direct production costs.', 'Gross profit divided by revenue is gross margin, a key profitability metric for goods producers.', 'Financial statements', 'Beginner', '{revenue,cost-of-goods-sold,gross-margin,operating-income}', '[]'::jsonb),
('operating-income', 'Operating income', 'Profit from core business operations, before interest and taxes.', 'Also called EBIT (earnings before interest and taxes). Strips out financing and tax structure to focus on operating performance.', 'Financial statements', 'Beginner', '{net-income,ebitda,operating-margin,income-statement}', '[]'::jsonb),
('net-income', 'Net income', 'The bottom-line profit after all expenses, interest, and taxes are subtracted from revenue.', 'Also called "earnings" or "the bottom line." Used directly in EPS and many valuation ratios.', 'Financial statements', 'Basic', '{eps,operating-income,income-statement,net-margin}', '[]'::jsonb),
('ebitda', 'EBITDA', 'Earnings before interest, taxes, depreciation, and amortization.', 'A rough proxy for operating cash flow that strips out financing decisions and non-cash charges. Widely used in M&A and leveraged finance.', 'Financial statements', 'Intermediate', '{ev-to-ebitda,operating-income,depreciation,amortization}', '[]'::jsonb),
('eps', 'Earnings per share (EPS)', 'Net income divided by shares outstanding — profit attributable to each share.', 'EPS is the most-watched profitability metric. Companies usually report both basic and diluted EPS.', 'Financial statements', 'Basic', '{diluted-eps,net-income,outstanding-shares,price-to-earnings-ratio}', '[]'::jsonb),
('diluted-eps', 'Diluted EPS', 'EPS computed assuming all convertible securities and options are exercised.', 'Diluted EPS is more conservative than basic EPS — it accounts for potential share count increases from stock options, RSUs, and convertibles.', 'Financial statements', 'Intermediate', '{eps,convertible-bond,outstanding-shares}', '[]'::jsonb),
('free-cash-flow', 'Free cash flow (FCF)', 'Cash generated from operations minus capital expenditures.', 'FCF is what''s available to return to shareholders or reinvest after sustaining the business. Many investors prefer it to net income.', 'Financial statements', 'Intermediate', '{operating-cash-flow,capex,cash-flow-statement,dcf}', '[]'::jsonb),
('operating-cash-flow', 'Operating cash flow (OCF)', 'Cash generated by a company''s normal business operations during a period.', 'OCF starts from net income and adds back non-cash charges, then adjusts for working capital changes. The most important line on the cash flow statement.', 'Financial statements', 'Intermediate', '{cash-flow-statement,free-cash-flow,accruals,depreciation}', '[]'::jsonb),
('capex', 'Capital expenditures (CapEx)', 'Money spent on long-lived assets like equipment, buildings, and infrastructure.', 'CapEx is shown on the cash flow statement under investing activities. Heavy CapEx now can mean lower current FCF but higher future capacity.', 'Financial statements', 'Beginner', '{free-cash-flow,cash-flow-statement,depreciation}', '[]'::jsonb),
('working-capital', 'Working capital', 'Current assets minus current liabilities — short-term operating liquidity.', 'Positive working capital means the company can cover near-term obligations. Changes in working capital affect operating cash flow.', 'Financial statements', 'Intermediate', '{current-ratio,quick-ratio,accounts-receivable,accounts-payable}', '[]'::jsonb),
('accounts-receivable', 'Accounts receivable', 'Money customers owe a company for goods or services already delivered.', 'AR sits on the balance sheet as a current asset. Rising AR relative to revenue can signal collection problems or aggressive revenue recognition.', 'Financial statements', 'Beginner', '{working-capital,balance-sheet,accounts-payable}', '[]'::jsonb),
('accounts-payable', 'Accounts payable', 'Money a company owes to suppliers for goods or services already received.', 'AP sits on the balance sheet as a current liability. Stretching AP is a common way to manage short-term cash flow.', 'Financial statements', 'Beginner', '{working-capital,balance-sheet,accounts-receivable}', '[]'::jsonb),
('goodwill', 'Goodwill', 'An intangible asset created when one company acquires another above book value.', 'Goodwill represents the premium paid for things like brand, customer relationships, and synergies. Tested annually for impairment.', 'Financial statements', 'Intermediate', '{balance-sheet,acquisition,merger}', '[]'::jsonb),
('accruals', 'Accruals', 'Accounting entries that record revenues or expenses before the related cash changes hands.', 'Accruals are why net income and cash flow can diverge. Forensic investors watch the spread for signs of earnings management.', 'Financial statements', 'Advanced', '{operating-cash-flow,deferred-revenue,income-statement}', '[]'::jsonb),
('depreciation', 'Depreciation', 'The systematic write-down of a tangible asset''s value over its useful life.', 'A non-cash expense on the income statement that reduces net income without reducing cash. Added back on the cash flow statement.', 'Financial statements', 'Beginner', '{amortization,capex,ebitda,operating-cash-flow}', '[]'::jsonb),
('amortization', 'Amortization', 'The systematic write-down of an intangible asset''s value over time.', 'Like depreciation but applied to intangibles such as patents and software. Also a non-cash charge.', 'Financial statements', 'Beginner', '{depreciation,goodwill,ebitda}', '[]'::jsonb),
('deferred-revenue', 'Deferred revenue', 'Cash received for goods or services not yet delivered, recorded as a liability.', 'Common for subscription businesses, where annual payments are recognized as revenue over the service period.', 'Financial statements', 'Intermediate', '{accruals,balance-sheet,revenue}', '[]'::jsonb),
('retained-earnings', 'Retained earnings', 'Cumulative net income a company has kept rather than paid out as dividends or buybacks.', 'Retained earnings sit in the equity section of the balance sheet and grow each year by net income less dividends.', 'Financial statements', 'Beginner', '{balance-sheet,equity,dividend,share-buyback}', '[]'::jsonb),
('comprehensive-income', 'Comprehensive income', 'Net income plus other gains and losses not flowing through the income statement.', 'Includes foreign-currency translation, unrealized gains on certain investments, and pension adjustments — items that affect equity but bypass net income.', 'Financial statements', 'Advanced', '{net-income,income-statement,equity}', '[]'::jsonb),

-- =================================================================
-- Ratios & valuation (25)
-- =================================================================
('price-to-earnings-ratio', 'Price-to-earnings (P/E) ratio', 'A stock''s price divided by its earnings per share — what investors pay for each dollar of earnings.', 'Higher P/Es generally signal higher growth expectations. Compare P/Es within industries, not across them — banks naturally trade lower than software.', 'Ratios & valuation', 'Basic', '{eps,peg-ratio,price-to-book-ratio,price-to-sales-ratio}', '[{"title":"Quick read","body":"A stock at $100 earning $5/share has a P/E of 20 — investors pay $20 for each $1 of current earnings."}]'::jsonb),
('price-to-book-ratio', 'Price-to-book (P/B) ratio', 'A stock''s price divided by its book value per share.', 'P/B below 1 means the market values the company at less than the accounting value of its assets. Common in value screens, especially for banks.', 'Ratios & valuation', 'Intermediate', '{book-value-per-share,price-to-earnings-ratio,value-stock}', '[]'::jsonb),
('price-to-sales-ratio', 'Price-to-sales (P/S) ratio', 'A stock''s price divided by revenue per share.', 'Useful for unprofitable or early-stage companies where P/E isn''t meaningful. Comparable to other companies in the same business model.', 'Ratios & valuation', 'Intermediate', '{revenue,price-to-earnings-ratio,growth-stock}', '[]'::jsonb),
('ev-to-ebitda', 'EV/EBITDA', 'Enterprise value divided by EBITDA — a capital-structure-neutral valuation multiple.', 'Preferred over P/E for comparing companies with different debt loads or for cross-border comparisons where tax regimes differ.', 'Ratios & valuation', 'Advanced', '{enterprise-value,ebitda,price-to-earnings-ratio}', '[]'::jsonb),
('enterprise-value', 'Enterprise value (EV)', 'Market cap plus debt minus cash — the theoretical takeover price of a company.', 'EV represents what an acquirer would pay for the entire business. Used in EV/EBITDA and EV/Sales multiples.', 'Ratios & valuation', 'Intermediate', '{market-capitalization,ev-to-ebitda,acquisition}', '[]'::jsonb),
('peg-ratio', 'PEG ratio', 'P/E ratio divided by expected earnings growth rate.', 'Below 1 is often considered cheap, above 2 expensive. Reduces the apples-to-oranges problem of comparing P/Es across growth profiles.', 'Ratios & valuation', 'Intermediate', '{price-to-earnings-ratio,growth-stock,eps}', '[]'::jsonb),
('dividend-yield', 'Dividend yield', 'Annual dividend per share divided by share price.', 'A yield rising solely because the share price is falling can signal distress, not opportunity. Always check whether the dividend looks sustainable.', 'Ratios & valuation', 'Basic', '{dividend,payout-ratio,yield}', '[]'::jsonb),
('payout-ratio', 'Payout ratio', 'Dividends paid divided by net income — what share of earnings goes to dividends.', 'Above 100% means the company is paying out more than it earns, which is unsustainable unless temporary.', 'Ratios & valuation', 'Beginner', '{dividend,dividend-yield,net-income}', '[]'::jsonb),
('return-on-equity', 'Return on equity (ROE)', 'Net income divided by shareholders'' equity — profit generated per dollar of equity.', 'High ROE signals an efficient business, but very high ROE often comes from heavy leverage. Pair with debt-to-equity for full context.', 'Ratios & valuation', 'Beginner', '{return-on-assets,return-on-invested-capital,equity,net-income}', '[]'::jsonb),
('return-on-assets', 'Return on assets (ROA)', 'Net income divided by total assets — profit generated per dollar of assets.', 'Unlike ROE, ROA isn''t inflated by leverage. Helpful when comparing companies with different capital structures.', 'Ratios & valuation', 'Intermediate', '{return-on-equity,return-on-invested-capital,balance-sheet}', '[]'::jsonb),
('return-on-invested-capital', 'Return on invested capital (ROIC)', 'After-tax operating profit divided by invested capital (debt + equity).', 'ROIC compared to WACC reveals whether the company is creating or destroying value with each dollar invested.', 'Ratios & valuation', 'Advanced', '{wacc,return-on-equity,return-on-assets}', '[]'::jsonb),
('debt-to-equity', 'Debt-to-equity ratio', 'Total debt divided by shareholders'' equity — a leverage measure.', 'High D/E magnifies both gains and losses. Capital-intensive industries (utilities, real estate) naturally run higher than asset-light ones.', 'Ratios & valuation', 'Beginner', '{equity,interest-coverage-ratio,balance-sheet}', '[]'::jsonb),
('current-ratio', 'Current ratio', 'Current assets divided by current liabilities — short-term liquidity.', 'Above 1 means the company can cover near-term obligations with current assets. Below 1 may signal stress.', 'Ratios & valuation', 'Beginner', '{quick-ratio,working-capital,balance-sheet}', '[]'::jsonb),
('quick-ratio', 'Quick ratio', 'Liquid current assets (excluding inventory) divided by current liabilities.', 'A stricter test than the current ratio because it excludes inventory, which may be hard to convert to cash quickly.', 'Ratios & valuation', 'Intermediate', '{current-ratio,working-capital,liquidity}', '[]'::jsonb),
('interest-coverage-ratio', 'Interest coverage ratio', 'Operating income divided by interest expense — how easily a company services its debt.', 'A ratio of 2x or below is often considered risky; healthy businesses typically run above 5x.', 'Ratios & valuation', 'Intermediate', '{debt-to-equity,operating-income,credit-rating}', '[]'::jsonb),
('gross-margin', 'Gross margin', 'Gross profit divided by revenue, expressed as a percentage.', 'Reflects pricing power and production efficiency. Software companies routinely run 70%+; commodity producers often under 20%.', 'Ratios & valuation', 'Beginner', '{gross-profit,revenue,operating-margin,net-margin}', '[]'::jsonb),
('operating-margin', 'Operating margin', 'Operating income divided by revenue — operating profitability.', 'Operating margin captures cost discipline across the whole organization, not just direct production.', 'Ratios & valuation', 'Beginner', '{operating-income,gross-margin,net-margin}', '[]'::jsonb),
('net-margin', 'Net margin', 'Net income divided by revenue — bottom-line profitability per dollar of sales.', 'The cleanest single-number summary of how much profit a business squeezes from each dollar of revenue.', 'Ratios & valuation', 'Beginner', '{net-income,operating-margin,gross-margin}', '[]'::jsonb),
('asset-turnover', 'Asset turnover', 'Revenue divided by total assets — how efficiently assets generate sales.', 'Retailers run high asset turnover with thin margins; utilities run low turnover with stable margins. Both can be good businesses.', 'Ratios & valuation', 'Intermediate', '{return-on-assets,balance-sheet,inventory-turnover}', '[]'::jsonb),
('inventory-turnover', 'Inventory turnover', 'Cost of goods sold divided by average inventory — how quickly inventory cycles.', 'High turnover means efficient inventory management; low turnover can indicate overstocking or weak demand.', 'Ratios & valuation', 'Intermediate', '{cost-of-goods-sold,asset-turnover,working-capital}', '[]'::jsonb),
('dcf', 'Discounted cash flow (DCF)', 'A valuation method projecting future cash flows and discounting them to present value.', 'DCF is theoretically rigorous but highly sensitive to assumptions about growth, margins, and discount rate. Small input changes swing the output dramatically.', 'Ratios & valuation', 'Advanced', '{free-cash-flow,terminal-value,wacc}', '[]'::jsonb),
('terminal-value', 'Terminal value', 'In a DCF, the value of cash flows beyond the explicit forecast period.', 'Often 60% to 80% of total DCF value, making the terminal growth assumption the most consequential lever in the model.', 'Ratios & valuation', 'Advanced', '{dcf,free-cash-flow,wacc}', '[]'::jsonb),
('wacc', 'Weighted average cost of capital (WACC)', 'A company''s blended cost of debt and equity capital, weighted by capital structure.', 'WACC is the discount rate used in DCFs. Lowering WACC raises valuations, which is why interest-rate moves swing equity prices.', 'Ratios & valuation', 'Advanced', '{dcf,return-on-invested-capital,debt-to-equity}', '[]'::jsonb),
('alpha', 'Alpha', 'Excess return relative to a benchmark, after adjusting for risk.', 'Generating alpha consistently is the holy grail of active management — and the empirical evidence shows most managers fail to deliver it net of fees.', 'Ratios & valuation', 'Intermediate', '{beta,sharpe-ratio,benchmark-index,return}', '[{"title":"Numeric example","body":"A fund returning 12% vs an 8% benchmark, with equal risk, has alpha of 4%."}]'::jsonb),
('book-value-per-share', 'Book value per share', 'Shareholders'' equity divided by outstanding shares.', 'Anchors the P/B ratio. Book value can understate true value for businesses with significant intangibles like brands or software.', 'Ratios & valuation', 'Intermediate', '{price-to-book-ratio,equity,outstanding-shares}', '[]'::jsonb),

-- =================================================================
-- Macro & monetary policy (25)
-- =================================================================
('federal-funds-rate', 'Federal funds rate', 'The interest rate at which U.S. banks lend reserves to each other overnight.', 'The Fed sets a target range and uses open market operations to enforce it. The fed funds rate is the foundational rate that ripples through all other U.S. interest rates.', 'Macro & monetary policy', 'Beginner', '{fomc,discount-rate,open-market-operations,yield-curve}', '[]'::jsonb),
('discount-rate', 'Discount rate', 'The rate the Fed charges banks for direct loans from the Federal Reserve''s discount window.', 'Typically set slightly above the fed funds rate. Borrowing from the discount window can signal a bank is in trouble, so it''s used sparingly.', 'Macro & monetary policy', 'Intermediate', '{federal-funds-rate,fomc}', '[]'::jsonb),
('open-market-operations', 'Open market operations', 'The Fed''s buying or selling of Treasury securities to manage the money supply.', 'Buying bonds injects reserves and lowers rates; selling drains reserves and raises rates. The main day-to-day tool of monetary policy.', 'Macro & monetary policy', 'Intermediate', '{federal-funds-rate,quantitative-easing,quantitative-tightening,money-supply}', '[]'::jsonb),
('quantitative-easing', 'Quantitative easing (QE)', 'Large-scale Fed asset purchases to lower long-term rates and stimulate the economy.', 'Used when short-term rates are already at zero. The Fed bought trillions in Treasuries and MBS after 2008 and again in 2020.', 'Macro & monetary policy', 'Intermediate', '{quantitative-tightening,open-market-operations,federal-funds-rate}', '[]'::jsonb),
('quantitative-tightening', 'Quantitative tightening (QT)', 'The Fed reducing its balance sheet by letting bonds mature without reinvesting.', 'QT is the reverse of QE. By shrinking reserves, it removes liquidity and tends to push long-term rates higher.', 'Macro & monetary policy', 'Intermediate', '{quantitative-easing,open-market-operations,money-supply}', '[]'::jsonb),
('fomc', 'FOMC (Federal Open Market Committee)', 'The Fed''s policy-setting body that decides interest rate moves and balance-sheet operations.', 'Twelve voting members (seven Fed governors plus five rotating regional bank presidents) meet eight times a year. Markets dissect every statement and projection.', 'Macro & monetary policy', 'Beginner', '{federal-funds-rate,open-market-operations,quantitative-easing}', '[]'::jsonb),
('inflation', 'Inflation', 'A sustained rise in the general price level, eroding purchasing power.', 'Measured by CPI and PCE in the U.S. The Fed targets 2% PCE inflation as consistent with its dual mandate.', 'Macro & monetary policy', 'Basic', '{consumer-price-index,pce,deflation,disinflation,real-return}', '[]'::jsonb),
('deflation', 'Deflation', 'A sustained decline in the general price level.', 'Sounds nice but is dangerous — falling prices encourage spending delays, which can spiral into a deeper economic contraction.', 'Macro & monetary policy', 'Intermediate', '{inflation,disinflation,recession}', '[]'::jsonb),
('stagflation', 'Stagflation', 'A rare combination of stagnant growth and high inflation.', 'The 1970s are the textbook example. Stagflation is hard for central banks because policy that fights one problem tends to worsen the other.', 'Macro & monetary policy', 'Advanced', '{inflation,recession,unemployment-rate}', '[]'::jsonb),
('disinflation', 'Disinflation', 'A slowdown in the rate of inflation — prices still rise, but more slowly.', 'Often confused with deflation. Central banks engineer disinflation through tighter policy without trying to push prices outright negative.', 'Macro & monetary policy', 'Intermediate', '{inflation,deflation,federal-funds-rate}', '[]'::jsonb),
('consumer-price-index', 'Consumer Price Index (CPI)', 'A measure of the average change in prices paid by urban consumers for a basket of goods and services.', 'Published monthly by the BLS. Headline CPI includes food and energy; core CPI excludes them for a less volatile read.', 'Macro & monetary policy', 'Beginner', '{inflation,core-inflation,pce,producer-price-index}', '[]'::jsonb),
('producer-price-index', 'Producer Price Index (PPI)', 'A measure of price changes received by domestic producers for their output.', 'PPI moves upstream of CPI — wholesale costs often feed through to consumer prices with a lag.', 'Macro & monetary policy', 'Intermediate', '{consumer-price-index,inflation}', '[]'::jsonb),
('core-inflation', 'Core inflation', 'Inflation excluding food and energy, which tend to be volatile.', 'Core measures give a cleaner signal of underlying inflation trends. The Fed weighs core PCE most heavily.', 'Macro & monetary policy', 'Intermediate', '{inflation,consumer-price-index,pce}', '[]'::jsonb),
('pce', 'PCE (Personal Consumption Expenditures)', 'A broader inflation measure tracking actual consumer spending patterns.', 'The Fed''s preferred inflation gauge because it adjusts for substitution effects as consumers shift purchases when prices change.', 'Macro & monetary policy', 'Intermediate', '{inflation,consumer-price-index,core-inflation}', '[]'::jsonb),
('gdp', 'Gross domestic product (GDP)', 'The total value of goods and services produced within a country''s borders over a period.', 'Reported quarterly and revised multiple times. Year-over-year real GDP growth is the headline measure of economic health.', 'Macro & monetary policy', 'Basic', '{real-gdp,nominal-gdp,recession,expansion}', '[]'::jsonb),
('real-gdp', 'Real GDP', 'GDP adjusted for inflation.', 'Real GDP isolates actual growth in output from price-level changes. The standard for comparing GDP across time periods.', 'Macro & monetary policy', 'Beginner', '{gdp,nominal-gdp,inflation,real-return}', '[]'::jsonb),
('nominal-gdp', 'Nominal GDP', 'GDP measured at current prices, without adjusting for inflation.', 'Useful for the size of an economy at a point in time but misleading for growth comparisons across periods of differing inflation.', 'Macro & monetary policy', 'Beginner', '{gdp,real-gdp,inflation}', '[]'::jsonb),
('recession', 'Recession', 'A significant decline in economic activity spread across the economy, lasting more than a few months.', 'Officially dated by the NBER in the U.S. A common shorthand is two consecutive quarters of negative real GDP, but NBER uses a broader definition.', 'Macro & monetary policy', 'Basic', '{expansion,business-cycle,gdp,unemployment-rate}', '[]'::jsonb),
('expansion', 'Expansion', 'The phase of the business cycle when economic activity is growing.', 'Expansions are typically much longer than recessions. The U.S. expansion from 2009 to 2020 was the longest on record.', 'Macro & monetary policy', 'Beginner', '{recession,business-cycle,gdp}', '[]'::jsonb),
('business-cycle', 'Business cycle', 'The recurring pattern of economic expansion and contraction.', 'Phases: expansion, peak, contraction (recession), trough. Cycle length varies but post-WWII U.S. cycles have averaged about 5 years.', 'Macro & monetary policy', 'Intermediate', '{recession,expansion,gdp}', '[]'::jsonb),
('unemployment-rate', 'Unemployment rate', 'The percentage of the labor force actively seeking work but not employed.', 'A lagging indicator of the business cycle. Doesn''t count discouraged workers who have stopped looking — the U6 rate captures broader underemployment.', 'Macro & monetary policy', 'Beginner', '{nonfarm-payrolls,recession,business-cycle}', '[]'::jsonb),
('nonfarm-payrolls', 'Nonfarm payrolls', 'The monthly net change in U.S. employment, excluding agricultural workers and a few small groups.', 'Released first Friday of each month by the BLS. Often the single most market-moving economic release.', 'Macro & monetary policy', 'Intermediate', '{unemployment-rate}', '[]'::jsonb),
('money-supply', 'Money supply', 'The total amount of money circulating in an economy.', 'Tracked in aggregates like M1 and M2. The Fed manages money supply through open market operations and reserve requirements.', 'Macro & monetary policy', 'Intermediate', '{m1,m2,open-market-operations,quantitative-easing}', '[]'::jsonb),
('m1', 'M1', 'The narrowest measure of money supply — cash, checking deposits, and other liquid deposits.', 'M1 captures money immediately usable for transactions. The Fed redefined M1 in 2020 to include savings deposits, sharply increasing the headline number.', 'Macro & monetary policy', 'Advanced', '{m2,money-supply}', '[]'::jsonb),
('m2', 'M2', 'A broader money measure — M1 plus small time deposits and retail money market funds.', 'M2 is more often cited because it tracks a wider definition of money available for spending or investment.', 'Macro & monetary policy', 'Advanced', '{m1,money-supply}', '[]'::jsonb),

-- =================================================================
-- Options & derivatives (25)
-- =================================================================
('call-option', 'Call option', 'A contract giving the holder the right to buy a stock at a set price before expiration.', 'Calls profit when the underlying rises. Buying calls is leverage on upside; selling calls collects premium but caps gains.', 'Options & derivatives', 'Beginner', '{put-option,strike-price,premium,expiration-date,covered-call}', '[]'::jsonb),
('put-option', 'Put option', 'A contract giving the holder the right to sell a stock at a set price before expiration.', 'Puts profit when the underlying falls. Used both for speculation and as portfolio insurance via protective puts.', 'Options & derivatives', 'Beginner', '{call-option,strike-price,premium,protective-put}', '[]'::jsonb),
('strike-price', 'Strike price', 'The fixed price at which an option can be exercised.', 'Together with expiration date, the strike defines an options contract. Moneyness (ITM/ATM/OTM) is measured relative to the strike.', 'Options & derivatives', 'Beginner', '{call-option,put-option,in-the-money,at-the-money,out-of-the-money}', '[]'::jsonb),
('expiration-date', 'Expiration date', 'The last day an option contract can be exercised.', 'After expiration, the option ceases to exist. Time decay accelerates as expiration approaches.', 'Options & derivatives', 'Beginner', '{call-option,put-option,theta,extrinsic-value}', '[]'::jsonb),
('in-the-money', 'In the money (ITM)', 'An option with intrinsic value — exercising it would produce a profit ignoring premium.', 'A call is ITM when the underlying is above the strike; a put is ITM when the underlying is below the strike.', 'Options & derivatives', 'Beginner', '{at-the-money,out-of-the-money,intrinsic-value,strike-price}', '[]'::jsonb),
('at-the-money', 'At the money (ATM)', 'An option whose strike equals (or is closest to) the current price of the underlying.', 'ATM options have no intrinsic value but the most extrinsic value — they''re the most sensitive to volatility changes.', 'Options & derivatives', 'Beginner', '{in-the-money,out-of-the-money,extrinsic-value,strike-price}', '[]'::jsonb),
('out-of-the-money', 'Out of the money (OTM)', 'An option that has no intrinsic value at the moment.', 'A call is OTM when the underlying is below strike; a put is OTM when above. OTM options are cheaper and more leveraged.', 'Options & derivatives', 'Beginner', '{in-the-money,at-the-money,intrinsic-value,strike-price}', '[]'::jsonb),
('premium', 'Option premium', 'The price paid by the buyer to the seller of an options contract.', 'Premium has two components: intrinsic value (if ITM) and extrinsic value (time + volatility).', 'Options & derivatives', 'Beginner', '{intrinsic-value,extrinsic-value,call-option,put-option}', '[]'::jsonb),
('intrinsic-value', 'Intrinsic value', 'The amount by which an option is in the money.', 'For a $100 call when the stock is at $107, intrinsic value is $7. Out-of-the-money options have zero intrinsic value.', 'Options & derivatives', 'Intermediate', '{extrinsic-value,in-the-money,premium}', '[]'::jsonb),
('extrinsic-value', 'Extrinsic value (time value)', 'The portion of an option''s premium beyond its intrinsic value.', 'Reflects time remaining and implied volatility. Decays toward zero by expiration — this is theta in action.', 'Options & derivatives', 'Intermediate', '{intrinsic-value,theta,implied-volatility,premium}', '[]'::jsonb),
('delta', 'Delta', 'An option''s sensitivity to a $1 move in the underlying price.', 'Delta of 0.50 means the option gains $0.50 for every $1 the stock rises. Also approximates the probability of finishing in the money.', 'Options & derivatives', 'Intermediate', '{gamma,theta,vega,rho}', '[]'::jsonb),
('gamma', 'Gamma', 'The rate at which delta changes as the underlying moves.', 'High gamma means delta moves quickly — ATM options near expiration have the highest gamma, making them the most explosive.', 'Options & derivatives', 'Advanced', '{delta,theta,vega}', '[]'::jsonb),
('theta', 'Theta', 'The amount an option''s price decays per day from time passage.', 'Theta is the option seller''s friend and the option buyer''s enemy. Accelerates as expiration approaches.', 'Options & derivatives', 'Intermediate', '{delta,gamma,extrinsic-value,expiration-date}', '[]'::jsonb),
('vega', 'Vega', 'An option''s sensitivity to a 1% change in implied volatility.', 'Long options have positive vega — they gain when volatility rises. Short options have negative vega.', 'Options & derivatives', 'Intermediate', '{delta,gamma,theta,implied-volatility}', '[]'::jsonb),
('rho', 'Rho', 'An option''s sensitivity to a 1% change in interest rates.', 'Usually the smallest of the Greeks for short-dated options, but matters for long-dated LEAPs.', 'Options & derivatives', 'Advanced', '{delta,gamma,theta,vega,federal-funds-rate}', '[]'::jsonb),
('implied-volatility', 'Implied volatility (IV)', 'The market''s expectation of future volatility, derived from option prices.', 'Rising IV makes all options more expensive, regardless of direction. The VIX is implied volatility on S&P 500 index options.', 'Options & derivatives', 'Intermediate', '{historical-volatility,vega,extrinsic-value}', '[]'::jsonb),
('historical-volatility', 'Historical volatility', 'The realized volatility of an asset measured from past price movements.', 'Compared with implied volatility to assess whether options are richly or cheaply priced relative to recent reality.', 'Options & derivatives', 'Intermediate', '{implied-volatility,standard-deviation}', '[]'::jsonb),
('covered-call', 'Covered call', 'Selling a call option against shares you already own.', 'Generates income from premium and caps upside at the strike. Popular income strategy for sideways markets.', 'Options & derivatives', 'Intermediate', '{call-option,premium,protective-put}', '[]'::jsonb),
('protective-put', 'Protective put', 'Buying a put option to hedge a long stock position.', 'Acts like portfolio insurance — defines maximum downside in exchange for the premium paid.', 'Options & derivatives', 'Intermediate', '{put-option,covered-call,premium}', '[]'::jsonb),
('straddle', 'Straddle', 'Buying both a call and a put at the same strike and expiration.', 'A bet on a big move in either direction. Profitable if the move exceeds the combined premium paid.', 'Options & derivatives', 'Advanced', '{strangle,iron-condor,implied-volatility}', '[]'::jsonb),
('strangle', 'Strangle', 'Buying an OTM call and OTM put at different strikes but the same expiration.', 'Cheaper than a straddle but requires a larger underlying move to profit. Common around earnings.', 'Options & derivatives', 'Advanced', '{straddle,iron-condor,out-of-the-money}', '[]'::jsonb),
('iron-condor', 'Iron condor', 'A four-leg options strategy selling OTM calls and puts while buying further OTM calls and puts.', 'Profits when the underlying stays in a defined range. Maximum loss and gain are both capped by the long wings.', 'Options & derivatives', 'Advanced', '{straddle,strangle,implied-volatility}', '[]'::jsonb),
('futures-contract', 'Futures contract', 'A standardized exchange-traded contract to buy or sell an asset at a future date and price.', 'Used for hedging and speculation. Marked-to-market daily, with margin calls when positions move against you.', 'Options & derivatives', 'Advanced', '{forward-contract,swap}', '[]'::jsonb),
('forward-contract', 'Forward contract', 'A private over-the-counter agreement to buy or sell at a future date and price.', 'Like futures but customized and not exchange-traded — so they carry counterparty risk.', 'Options & derivatives', 'Advanced', '{futures-contract,swap}', '[]'::jsonb),
('swap', 'Swap', 'A derivative where two parties exchange cash flows based on different underlyings.', 'Interest rate swaps (fixed for floating) are by far the largest category. Also used for currencies, commodities, and credit (CDS).', 'Options & derivatives', 'Advanced', '{futures-contract,forward-contract}', '[]'::jsonb),

-- =================================================================
-- ETFs & funds (15)
-- =================================================================
('etf', 'Exchange-traded fund (ETF)', 'A pooled investment fund that trades on an exchange like a stock.', 'ETFs combine mutual fund diversification with intraday tradability and typically lower expense ratios. Most are passively managed index trackers.', 'ETFs & funds', 'Basic', '{mutual-fund,index-fund,expense-ratio,net-asset-value}', '[]'::jsonb),
('mutual-fund', 'Mutual fund', 'A pooled investment vehicle that buys and sells once per day at end-of-day NAV.', 'Mutual funds offer professional management and easy access but lack intraday pricing. Many actively managed funds charge higher fees than ETFs.', 'ETFs & funds', 'Basic', '{etf,index-fund,actively-managed-fund,expense-ratio}', '[]'::jsonb),
('index-fund', 'Index fund', 'A fund designed to replicate the performance of a market index.', 'Index funds embody the passive investing thesis: most active managers underperform after fees, so just own the market cheaply.', 'ETFs & funds', 'Basic', '{etf,mutual-fund,tracking-error,expense-ratio}', '[]'::jsonb),
('actively-managed-fund', 'Actively managed fund', 'A fund whose manager picks securities trying to beat a benchmark.', 'Active funds charge higher fees to support research and trading. Net of fees, most underperform their benchmarks over long periods.', 'ETFs & funds', 'Beginner', '{index-fund,mutual-fund,alpha,expense-ratio}', '[]'::jsonb),
('expense-ratio', 'Expense ratio', 'The annual fee a fund charges, expressed as a percentage of assets.', 'A 0.05% ratio means $5 per year per $10,000 invested. Over decades, even small differences in fees compound into large gaps in ending wealth.', 'ETFs & funds', 'Beginner', '{mutual-fund,etf,index-fund}', '[]'::jsonb),
('tracking-error', 'Tracking error', 'The standard deviation of a fund''s returns relative to its benchmark.', 'Lower is better for index funds. Caused by fees, transaction costs, sampling, and cash drag.', 'ETFs & funds', 'Intermediate', '{index-fund,etf,benchmark-index}', '[]'::jsonb),
('net-asset-value', 'Net asset value (NAV)', 'A fund''s per-share value — assets minus liabilities, divided by shares outstanding.', 'Mutual funds transact at NAV once a day. ETFs trade near NAV intraday, kept in line by arbitrage from authorized participants.', 'ETFs & funds', 'Intermediate', '{mutual-fund,etf,authorized-participant,creation-unit}', '[]'::jsonb),
('creation-unit', 'Creation unit', 'A large block of ETF shares (typically 50,000) created or redeemed by authorized participants.', 'The creation/redemption mechanism is what keeps ETF prices close to NAV and gives ETFs their tax efficiency.', 'ETFs & funds', 'Advanced', '{authorized-participant,etf,net-asset-value}', '[]'::jsonb),
('authorized-participant', 'Authorized participant (AP)', 'A large institutional firm authorized to create and redeem ETF shares directly with the issuer.', 'APs arbitrage premium/discount gaps between an ETF''s price and its NAV, keeping the two aligned.', 'ETFs & funds', 'Advanced', '{creation-unit,etf,net-asset-value}', '[]'::jsonb),
('leveraged-etf', 'Leveraged ETF', 'An ETF that uses derivatives to deliver a multiple of an index''s daily return.', 'Designed to be held for a single day. Compounding effects make returns over longer periods diverge significantly from the multiple.', 'ETFs & funds', 'Advanced', '{etf,inverse-etf,futures-contract}', '[]'::jsonb),
('inverse-etf', 'Inverse ETF', 'An ETF designed to move opposite an index on a daily basis.', 'Like leveraged ETFs, inverse ETFs are short-term instruments. Decay from daily rebalancing hurts long-term performance.', 'ETFs & funds', 'Advanced', '{etf,leveraged-etf,short-selling}', '[]'::jsonb),
('closed-end-fund', 'Closed-end fund', 'A fund that issues a fixed number of shares and trades on an exchange, often at a premium or discount to NAV.', 'Unlike ETFs, closed-end funds have no creation/redemption mechanism, so their market price can diverge meaningfully from NAV.', 'ETFs & funds', 'Advanced', '{open-end-fund,etf,net-asset-value}', '[]'::jsonb),
('open-end-fund', 'Open-end fund', 'A fund that continuously issues and redeems shares at NAV — the standard mutual fund structure.', 'Open-end means the share count expands and contracts with investor flows, in contrast to closed-end funds.', 'ETFs & funds', 'Intermediate', '{closed-end-fund,mutual-fund,net-asset-value}', '[]'::jsonb),
('hedge-fund', 'Hedge fund', 'A private investment partnership that uses a wide range of strategies, often including leverage and shorting.', 'Limited to accredited investors. Charges performance fees on top of management fees ("2 and 20" being the classic structure).', 'ETFs & funds', 'Advanced', '{actively-managed-fund,short-selling,alpha}', '[]'::jsonb),
('fund-of-funds', 'Fund of funds', 'A fund that invests in other funds rather than directly in securities.', 'Offers diversification across managers in a single product, but layers fees on top of underlying fund expenses.', 'ETFs & funds', 'Intermediate', '{hedge-fund,mutual-fund,expense-ratio}', '[]'::jsonb),

-- =================================================================
-- Technical analysis (20)
-- =================================================================
('simple-moving-average', 'Simple moving average (SMA)', 'The average closing price over a set number of periods, recalculated each period.', 'The 50-day and 200-day SMAs are widely watched. Price crossing the 200-day is a common trend signal.', 'Technical analysis', 'Beginner', '{exponential-moving-average,golden-cross,trendline}', '[]'::jsonb),
('exponential-moving-average', 'Exponential moving average (EMA)', 'A moving average that weights recent prices more heavily than older ones.', 'EMAs respond faster to price changes than SMAs, which appeals to shorter-term traders.', 'Technical analysis', 'Beginner', '{simple-moving-average,macd}', '[]'::jsonb),
('relative-strength-index', 'Relative strength index (RSI)', 'A momentum oscillator measuring the magnitude of recent gains versus losses on a 0–100 scale.', 'Above 70 is conventionally overbought, below 30 oversold. Divergences from price often precede reversals.', 'Technical analysis', 'Intermediate', '{stochastic-oscillator,macd}', '[]'::jsonb),
('macd', 'MACD', 'Moving Average Convergence Divergence — the difference between two EMAs, plotted with a signal line.', 'Crossovers of the MACD line above or below the signal line generate trade signals.', 'Technical analysis', 'Intermediate', '{exponential-moving-average,relative-strength-index}', '[]'::jsonb),
('bollinger-bands', 'Bollinger Bands', 'Volatility bands plotted above and below a moving average at standard-deviation intervals.', 'Prices touching the upper band suggest overextension; squeezes (narrowing bands) often precede explosive moves.', 'Technical analysis', 'Intermediate', '{simple-moving-average,standard-deviation,average-true-range}', '[]'::jsonb),
('support', 'Support', 'A price level where buying interest historically halts declines.', 'Support often turns into resistance once broken — and vice versa.', 'Technical analysis', 'Beginner', '{resistance,trendline}', '[]'::jsonb),
('resistance', 'Resistance', 'A price level where selling pressure historically halts advances.', 'Resistance levels often form at prior highs, round numbers, or technical retracement levels.', 'Technical analysis', 'Beginner', '{support,trendline,fibonacci-retracement}', '[]'::jsonb),
('trendline', 'Trendline', 'A straight line connecting price highs or lows to visualize a trend''s direction.', 'Up-trends connect rising lows; down-trends connect falling highs. Trendline breaks often signal trend changes.', 'Technical analysis', 'Beginner', '{support,resistance}', '[]'::jsonb),
('head-and-shoulders', 'Head and shoulders', 'A reversal chart pattern with three peaks — the middle (head) higher than the two flanking shoulders.', 'A break below the neckline confirms the pattern and projects a target equal to the head-to-neckline distance.', 'Technical analysis', 'Intermediate', '{double-top,double-bottom,trendline}', '[]'::jsonb),
('double-top', 'Double top', 'A bearish reversal pattern with two peaks at roughly the same price.', 'Confirmed by a break below the trough between the peaks. The target is typically the peak-to-trough height projected down.', 'Technical analysis', 'Intermediate', '{double-bottom,head-and-shoulders,resistance}', '[]'::jsonb),
('double-bottom', 'Double bottom', 'A bullish reversal pattern with two troughs at roughly the same price.', 'The mirror image of a double top. Confirmed by a break above the intervening peak.', 'Technical analysis', 'Intermediate', '{double-top,head-and-shoulders,support}', '[]'::jsonb),
('cup-and-handle', 'Cup and handle', 'A bullish continuation pattern resembling a teacup followed by a small downward drift.', 'Popularized by William O''Neil. The breakout from the handle is the entry signal.', 'Technical analysis', 'Advanced', '{trendline,support,resistance}', '[]'::jsonb),
('candlestick', 'Candlestick', 'A chart format showing open, high, low, and close prices as a "candle" with a body and wicks.', 'Originally from Japanese rice markets. The shape and color reveal intraperiod price action at a glance.', 'Technical analysis', 'Beginner', '{doji}', '[]'::jsonb),
('doji', 'Doji', 'A candlestick where the open and close are nearly equal, creating a thin body.', 'Signals indecision. After a strong trend, a doji often warns of a possible reversal.', 'Technical analysis', 'Intermediate', '{candlestick}', '[]'::jsonb),
('fibonacci-retracement', 'Fibonacci retracement', 'Horizontal lines drawn at key Fibonacci percentages (23.6%, 38.2%, 50%, 61.8%) to identify potential support and resistance.', 'Used to project where pullbacks within a trend might end. Has cult following despite weak statistical evidence.', 'Technical analysis', 'Intermediate', '{support,resistance,trendline}', '[]'::jsonb),
('volume', 'Volume', 'The number of shares or contracts traded in a security or market over a period.', 'Volume confirms price action — breakouts on heavy volume are more credible than those on light volume.', 'Technical analysis', 'Beginner', '{on-balance-volume,liquidity}', '[]'::jsonb),
('on-balance-volume', 'On-balance volume (OBV)', 'A momentum indicator that adds volume on up days and subtracts on down days.', 'Used to detect divergences between volume and price that may precede reversals.', 'Technical analysis', 'Intermediate', '{volume}', '[]'::jsonb),
('average-true-range', 'Average true range (ATR)', 'A volatility measure averaging the daily price range over a period.', 'ATR is commonly used to size positions and set stop-loss distances proportional to volatility.', 'Technical analysis', 'Intermediate', '{bollinger-bands,standard-deviation}', '[]'::jsonb),
('stochastic-oscillator', 'Stochastic oscillator', 'A momentum indicator comparing closing price to its recent high-low range, plotted 0–100.', 'Like RSI, has conventional overbought (>80) and oversold (<20) thresholds.', 'Technical analysis', 'Intermediate', '{relative-strength-index,macd}', '[]'::jsonb),
('golden-cross', 'Golden cross', 'A bullish signal triggered when a short-term moving average crosses above a long-term moving average.', 'The classic version is the 50-day SMA crossing above the 200-day. The opposite is the death cross.', 'Technical analysis', 'Intermediate', '{simple-moving-average,exponential-moving-average,trendline}', '[]'::jsonb),

-- =================================================================
-- Corporate actions (15)
-- =================================================================
('dividend-declaration', 'Dividend declaration', 'A company''s formal announcement of a dividend amount, record date, and payment date.', 'On declaration, the dividend becomes a legal liability of the company.', 'Corporate actions', 'Beginner', '{dividend,ex-dividend-date,record-date,payment-date}', '[]'::jsonb),
('ex-dividend-date', 'Ex-dividend date', 'The first trading day on which buyers are no longer entitled to the upcoming dividend.', 'Stocks typically drop by approximately the dividend amount on the ex-dividend date.', 'Corporate actions', 'Beginner', '{dividend,record-date,dividend-declaration}', '[]'::jsonb),
('record-date', 'Record date', 'The date a company checks its books to determine which shareholders receive a declared dividend.', 'Set by the company alongside the dividend declaration. Owners as of the record date get paid.', 'Corporate actions', 'Beginner', '{ex-dividend-date,payment-date,dividend-declaration}', '[]'::jsonb),
('payment-date', 'Payment date', 'The date a declared dividend is actually paid to eligible shareholders.', 'Usually a few weeks after the record date.', 'Corporate actions', 'Beginner', '{dividend,record-date,dividend-declaration}', '[]'::jsonb),
('special-dividend', 'Special dividend', 'A one-time distribution outside a company''s regular dividend schedule.', 'Often paid after asset sales or windfall profits. Can be much larger than regular quarterly dividends.', 'Corporate actions', 'Intermediate', '{dividend,dividend-declaration}', '[]'::jsonb),
('stock-dividend', 'Stock dividend', 'A dividend paid in additional shares instead of cash.', 'Increases share count but not the company''s overall value — each shareholder ends up with proportionally more shares.', 'Corporate actions', 'Intermediate', '{dividend,stock-split,outstanding-shares}', '[]'::jsonb),
('spin-off', 'Spin-off', 'A corporate action that creates a new independent company by distributing shares of a subsidiary.', 'Existing shareholders typically receive shares in the new entity pro-rata. Aimed at unlocking value in a non-core business.', 'Corporate actions', 'Intermediate', '{merger,acquisition,share-class}', '[]'::jsonb),
('merger', 'Merger', 'Two companies combining to form one new entity.', 'Differs from acquisition in that mergers are typically "of equals," though pure equal mergers are rare in practice.', 'Corporate actions', 'Beginner', '{acquisition,tender-offer,goodwill}', '[]'::jsonb),
('acquisition', 'Acquisition', 'One company buying another, with the target typically ceasing to exist as an independent entity.', 'Can be friendly or hostile, cash or stock, asset-based or equity-based. Premiums above market price are normal.', 'Corporate actions', 'Beginner', '{merger,tender-offer,goodwill,enterprise-value}', '[]'::jsonb),
('tender-offer', 'Tender offer', 'A public offer to buy shareholders'' shares at a stated price.', 'A common acquisition tactic that bypasses target-company management. Often premium to market price.', 'Corporate actions', 'Intermediate', '{acquisition,merger,proxy-vote}', '[]'::jsonb),
('proxy-vote', 'Proxy vote', 'A shareholder''s vote cast on their behalf at a corporate meeting via a proxy form.', 'Most retail shareholders vote by proxy rather than attending annual meetings. Proxy fights are battles for board control.', 'Corporate actions', 'Intermediate', '{voting-rights,shareholder,tender-offer}', '[]'::jsonb),
('rights-offering', 'Rights offering', 'An issuance of new shares offered first to existing shareholders, usually at a discount.', 'Lets the company raise capital while letting existing holders avoid dilution by participating pro-rata.', 'Corporate actions', 'Advanced', '{secondary-offering,warrants}', '[]'::jsonb),
('warrants', 'Warrants', 'Long-dated rights to buy a company''s stock at a fixed price.', 'Similar to long-term call options but issued by the company itself. Often attached to bond or preferred offerings as a sweetener.', 'Corporate actions', 'Advanced', '{call-option,rights-offering}', '[]'::jsonb),
('delisting', 'Delisting', 'Removing a stock from an exchange listing, often involuntary due to falling below listing requirements.', 'Delisted stocks may continue trading OTC at much lower liquidity. Voluntary delisting can also occur when a company goes private.', 'Corporate actions', 'Intermediate', '{reverse-stock-split,bankruptcy}', '[]'::jsonb),
('bankruptcy', 'Bankruptcy', 'A legal process when a company cannot meet its debts and seeks court protection.', 'Chapter 11 reorganizes; Chapter 7 liquidates. Equity is usually wiped out — bondholders typically recover a fraction of par.', 'Corporate actions', 'Intermediate', '{delisting,credit-rating,equity}', '[]'::jsonb),

-- =================================================================
-- Crypto (15)
-- =================================================================
('blockchain', 'Blockchain', 'A distributed, append-only ledger of transactions cryptographically linked into blocks.', 'Underpins Bitcoin, Ethereum, and most crypto assets. Each new block references the previous, making historical changes extremely difficult.', 'Crypto', 'Basic', '{bitcoin,ethereum,smart-contract,proof-of-work}', '[]'::jsonb),
('smart-contract', 'Smart contract', 'Code that runs automatically on a blockchain when conditions are met.', 'Pioneered by Ethereum. Power applications from DeFi protocols to NFTs to DAOs.', 'Crypto', 'Intermediate', '{ethereum,defi,dao,nft}', '[]'::jsonb),
('stablecoin', 'Stablecoin', 'A cryptocurrency designed to maintain a fixed value, typically pegged to the U.S. dollar.', 'Backed by reserves (USDC, USDT), overcollateralized crypto (DAI), or algorithms (mostly failed). Critical plumbing for crypto trading.', 'Crypto', 'Beginner', '{defi,blockchain}', '[]'::jsonb),
('defi', 'DeFi (Decentralized Finance)', 'Financial services — lending, trading, derivatives — built on public blockchains via smart contracts.', 'Aims to recreate traditional finance without intermediaries. Hugely innovative but plagued by exploits and regulatory uncertainty.', 'Crypto', 'Intermediate', '{smart-contract,ethereum,stablecoin,layer-2}', '[]'::jsonb),
('layer-2', 'Layer 2', 'A protocol built on top of a base blockchain (Layer 1) to scale transactions cheaply.', 'On Ethereum, examples include Arbitrum and Optimism. Bundle transactions off-chain and post compressed proofs back to Layer 1.', 'Crypto', 'Advanced', '{ethereum,blockchain,gas-fee}', '[]'::jsonb),
('bitcoin', 'Bitcoin', 'The original cryptocurrency, launched in 2009, running on a proof-of-work blockchain.', 'Hard-capped at 21 million coins. Treated by many investors as digital gold — a non-sovereign store of value.', 'Crypto', 'Basic', '{blockchain,proof-of-work,mining}', '[]'::jsonb),
('ethereum', 'Ethereum', 'A programmable blockchain that supports smart contracts and tokenized assets.', 'Transitioned from proof-of-work to proof-of-stake in 2022 ("The Merge"). Hosts most of DeFi and NFTs.', 'Crypto', 'Beginner', '{blockchain,smart-contract,proof-of-stake,gas-fee,defi}', '[]'::jsonb),
('wallet', 'Crypto wallet', 'Software or hardware that stores the private keys needed to access cryptocurrency.', '"Hot" wallets are online and convenient; "cold" wallets (hardware devices) are offline and far more secure for long-term storage.', 'Crypto', 'Beginner', '{private-key,blockchain}', '[]'::jsonb),
('private-key', 'Private key', 'A cryptographic secret that authorizes spending from a crypto wallet.', 'Losing a private key means losing access permanently — there''s no password reset. Famous case: hundreds of thousands of bitcoins lost forever.', 'Crypto', 'Intermediate', '{wallet,blockchain}', '[]'::jsonb),
('proof-of-work', 'Proof of work', 'A consensus mechanism that secures the blockchain by requiring miners to solve computational puzzles.', 'Bitcoin uses PoW. Highly secure but energy-intensive — a frequent target of environmental criticism.', 'Crypto', 'Intermediate', '{bitcoin,mining,proof-of-stake}', '[]'::jsonb),
('proof-of-stake', 'Proof of stake', 'A consensus mechanism that selects validators in proportion to the crypto they''ve locked up as collateral.', 'Far more energy-efficient than proof of work. Ethereum migrated to PoS in 2022.', 'Crypto', 'Intermediate', '{proof-of-work,ethereum}', '[]'::jsonb),
('mining', 'Crypto mining', 'The process of validating transactions and adding new blocks to a proof-of-work blockchain in exchange for rewards.', 'Bitcoin mining has industrialized into massive ASIC-powered data centers, often located near cheap electricity.', 'Crypto', 'Intermediate', '{proof-of-work,bitcoin,blockchain}', '[]'::jsonb),
('nft', 'NFT (Non-Fungible Token)', 'A blockchain token representing unique ownership of a specific digital or physical asset.', 'Unlike fungible tokens (one bitcoin equals another), each NFT is unique. Used for art, collectibles, in-game items, and identity.', 'Crypto', 'Beginner', '{smart-contract,ethereum,blockchain}', '[]'::jsonb),
('dao', 'DAO (Decentralized Autonomous Organization)', 'An organization governed by token-holder voting and smart contracts rather than traditional management.', 'Treasury decisions, protocol changes, and grants all flow through on-chain governance proposals.', 'Crypto', 'Advanced', '{smart-contract,defi,ethereum}', '[]'::jsonb),
('gas-fee', 'Gas fee', 'The fee paid to validators to process a transaction or execute a smart contract on a blockchain.', 'Gas spikes during periods of high network demand. Layer 2 networks dramatically reduce gas costs.', 'Crypto', 'Beginner', '{ethereum,layer-2,smart-contract}', '[]'::jsonb),

-- =================================================================
-- Behavioral finance (15)
-- =================================================================
('anchoring', 'Anchoring', 'The cognitive bias of relying too heavily on the first piece of information encountered.', 'In investing, the price you paid for a stock often anchors decisions to hold or sell, even when that price is irrelevant to future returns.', 'Behavioral finance', 'Beginner', '{recency-bias,confirmation-bias,disposition-effect}', '[]'::jsonb),
('fomo', 'FOMO (Fear of Missing Out)', 'The anxiety that drives investors to chase rising prices for fear of being left behind.', 'FOMO peaks near market tops, when prices have already risen substantially. A classic source of buying high and selling low.', 'Behavioral finance', 'Basic', '{herd-behavior,recency-bias,greed-and-fear-index}', '[]'::jsonb),
('loss-aversion', 'Loss aversion', 'The tendency to feel losses about twice as strongly as equivalent gains.', 'A key insight from prospect theory. Explains why investors hold losing positions too long and sell winners too soon.', 'Behavioral finance', 'Beginner', '{prospect-theory,disposition-effect,sunk-cost-fallacy}', '[]'::jsonb),
('herd-behavior', 'Herd behavior', 'The tendency for investors to follow what others are doing rather than independent analysis.', 'Drives bubbles and crashes. Social media has amplified herd behavior dramatically in modern markets.', 'Behavioral finance', 'Beginner', '{fomo,animal-spirits,greed-and-fear-index}', '[]'::jsonb),
('recency-bias', 'Recency bias', 'Weighting recent events more heavily than older information when making decisions.', 'After a bull market, investors expect continued gains; after a crash, they expect more losses. Both extrapolate recent past too far.', 'Behavioral finance', 'Beginner', '{anchoring,availability-heuristic,fomo}', '[]'::jsonb),
('confirmation-bias', 'Confirmation bias', 'The tendency to seek out information that confirms existing beliefs and dismiss what contradicts them.', 'A trap for investors who become married to a thesis. Actively seeking the strongest counterarguments is a discipline against this.', 'Behavioral finance', 'Beginner', '{overconfidence-bias,anchoring}', '[]'::jsonb),
('overconfidence-bias', 'Overconfidence bias', 'Believing one''s judgment and skill are better than they actually are.', 'Linked to excessive trading, underdiversification, and concentrated bets. Active traders persistently underperform indices.', 'Behavioral finance', 'Beginner', '{confirmation-bias,recency-bias}', '[]'::jsonb),
('availability-heuristic', 'Availability heuristic', 'Judging the probability of an event by how easily examples come to mind.', 'Investors overweight recent or vivid events — a plane crash makes flying feel riskier than driving, even though it''s far safer.', 'Behavioral finance', 'Intermediate', '{recency-bias,anchoring}', '[]'::jsonb),
('mental-accounting', 'Mental accounting', 'Treating money differently based on its source or intended use.', 'A bonus may be "play money" gambled aggressively, while salary is "real money" saved conservatively — even though all dollars are fungible.', 'Behavioral finance', 'Intermediate', '{loss-aversion,prospect-theory}', '[]'::jsonb),
('disposition-effect', 'Disposition effect', 'The tendency to sell winning positions too soon and hold losing positions too long.', 'A direct consequence of loss aversion. Realized gains feel good; locking in losses feels bad — even when both decisions are equally rational.', 'Behavioral finance', 'Intermediate', '{loss-aversion,sunk-cost-fallacy,prospect-theory}', '[]'::jsonb),
('sunk-cost-fallacy', 'Sunk cost fallacy', 'Continuing an investment because of past commitments rather than future prospects.', 'Past costs are gone regardless of what you do next. Only future expected returns should drive the decision to hold or sell.', 'Behavioral finance', 'Beginner', '{loss-aversion,disposition-effect}', '[]'::jsonb),
('endowment-effect', 'Endowment effect', 'Valuing things more highly simply because you own them.', 'Investors demand higher prices to part with stocks they own than they would pay to acquire them — a quirk that distorts portfolio decisions.', 'Behavioral finance', 'Intermediate', '{loss-aversion,disposition-effect}', '[]'::jsonb),
('prospect-theory', 'Prospect theory', 'A behavioral framework showing people evaluate gains and losses asymmetrically relative to a reference point.', 'Developed by Kahneman and Tversky. Replaces the older expected-utility model that assumed rational risk-aversion.', 'Behavioral finance', 'Advanced', '{loss-aversion,mental-accounting,disposition-effect}', '[]'::jsonb),
('animal-spirits', 'Animal spirits', 'Keynes''s term for the emotional drivers — confidence, fear, optimism — that move markets beyond pure rationality.', 'Resurfaces in modern behavioral finance as a way to describe sentiment-driven price moves disconnected from fundamentals.', 'Behavioral finance', 'Intermediate', '{herd-behavior,greed-and-fear-index}', '[]'::jsonb),
('greed-and-fear-index', 'Greed and Fear Index', 'A composite indicator measuring market sentiment from extreme fear to extreme greed.', 'CNN''s version blends seven sub-indicators. Useful as a contrarian gauge — extreme greed often marks tops, extreme fear marks bottoms.', 'Behavioral finance', 'Beginner', '{fomo,herd-behavior,animal-spirits}', '[]'::jsonb),

-- =================================================================
-- Taxes & retirement (15)
-- =================================================================
('traditional-ira', 'Traditional IRA', 'A retirement account funded with pre-tax dollars, with taxes paid on withdrawal.', 'Contributions may be tax-deductible. Required minimum distributions kick in starting at age 73.', 'Taxes & retirement', 'Beginner', '{roth-ira,rmd,roth-conversion}', '[]'::jsonb),
('roth-ira', 'Roth IRA', 'A retirement account funded with after-tax dollars; qualified withdrawals are tax-free.', 'No RMDs during the owner''s lifetime. Income limits restrict who can contribute directly.', 'Taxes & retirement', 'Beginner', '{traditional-ira,backdoor-roth,roth-conversion,qualified-dividend}', '[]'::jsonb),
('employer-401k', 'Employer 401(k) plan', 'A workplace retirement plan where employees defer salary into investments, often with employer matching.', 'Contribution limits are far higher than IRAs. Matching contributions are effectively free money — capturing the full match should be a priority.', 'Taxes & retirement', 'Beginner', '{defined-contribution-plan,defined-benefit-plan,mega-backdoor-roth}', '[]'::jsonb),
('defined-contribution-plan', 'Defined contribution plan', 'A retirement plan where contributions are specified but final benefits depend on investment returns.', '401(k)s and IRAs are defined contribution. The employee bears the investment risk.', 'Taxes & retirement', 'Intermediate', '{employer-401k,defined-benefit-plan,traditional-ira}', '[]'::jsonb),
('defined-benefit-plan', 'Defined benefit plan', 'A pension that promises a specific retirement payout based on salary and years of service.', 'The employer bears the investment risk. Increasingly rare in the private sector, still common in government and unions.', 'Taxes & retirement', 'Intermediate', '{defined-contribution-plan,employer-401k}', '[]'::jsonb),
('capital-gains-tax', 'Capital gains tax', 'Tax on the profit from selling investments held outside tax-advantaged accounts.', 'Federal rates depend on holding period and income bracket. State taxes apply on top in many states.', 'Taxes & retirement', 'Beginner', '{long-term-capital-gain,short-term-capital-gain,wash-sale-rule}', '[]'::jsonb),
('long-term-capital-gain', 'Long-term capital gain', 'A gain on an asset held more than one year, taxed at preferential federal rates (0%, 15%, or 20%).', 'Holding past the one-year mark can substantially reduce taxes versus short-term rates.', 'Taxes & retirement', 'Beginner', '{capital-gain,short-term-capital-gain,capital-gains-tax}', '[]'::jsonb),
('short-term-capital-gain', 'Short-term capital gain', 'A gain on an asset held one year or less, taxed as ordinary income.', 'Tax rates can be nearly double those on long-term gains for high earners, which discourages frequent trading in taxable accounts.', 'Taxes & retirement', 'Beginner', '{capital-gain,long-term-capital-gain,capital-gains-tax}', '[]'::jsonb),
('wash-sale-rule', 'Wash sale rule', 'An IRS rule disallowing the tax loss on a security if a substantially identical one is bought within 30 days before or after the sale.', 'Designed to prevent tax-loss harvesting without actually changing your economic position. Easy to trip on accidentally.', 'Taxes & retirement', 'Intermediate', '{tax-loss-harvesting,capital-loss}', '[]'::jsonb),
('tax-loss-harvesting', 'Tax-loss harvesting', 'Selling losing positions to realize losses that offset gains for tax purposes.', 'Must navigate the wash sale rule to preserve the loss. A common year-end portfolio housekeeping practice.', 'Taxes & retirement', 'Intermediate', '{wash-sale-rule,capital-loss,capital-gain}', '[]'::jsonb),
('rmd', 'Required minimum distribution (RMD)', 'The minimum amount that must be withdrawn from most retirement accounts annually starting at age 73.', 'RMDs are taxed as ordinary income. Missing one carries a steep penalty (now 25%, reduced from 50%).', 'Taxes & retirement', 'Intermediate', '{traditional-ira,employer-401k,roth-ira}', '[]'::jsonb),
('roth-conversion', 'Roth conversion', 'Moving money from a traditional IRA into a Roth IRA, paying tax now in exchange for tax-free future growth.', 'Often done in low-income years (early retirement, sabbatical) to lock in lower tax rates.', 'Taxes & retirement', 'Advanced', '{traditional-ira,roth-ira,backdoor-roth}', '[]'::jsonb),
('backdoor-roth', 'Backdoor Roth', 'A strategy to fund a Roth IRA above income limits by contributing to a traditional IRA and immediately converting.', 'Watch the pro-rata rule: pre-tax IRA balances make the conversion partially taxable. Cleanest when no other IRA money exists.', 'Taxes & retirement', 'Advanced', '{roth-ira,traditional-ira,roth-conversion}', '[]'::jsonb),
('mega-backdoor-roth', 'Mega backdoor Roth', 'A strategy using after-tax 401(k) contributions and in-plan conversions to push tens of thousands extra into a Roth.', 'Requires a plan that supports after-tax contributions and either in-service distributions or in-plan Roth rollovers.', 'Taxes & retirement', 'Advanced', '{employer-401k,backdoor-roth,roth-ira}', '[]'::jsonb),
('qualified-dividend', 'Qualified dividend', 'A dividend eligible for the lower long-term capital gains tax rate rather than ordinary income rates.', 'Most U.S. corporate dividends qualify, provided the holder meets the holding-period requirement around the ex-dividend date.', 'Taxes & retirement', 'Intermediate', '{dividend,long-term-capital-gain,ex-dividend-date}', '[]'::jsonb),

-- =================================================================
-- Risk & portfolio management (15)
-- =================================================================
('diversification', 'Diversification', 'Spreading investments across assets to reduce exposure to any single one.', 'The "only free lunch" in finance — diversification can reduce risk without sacrificing expected return, as long as the holdings aren''t perfectly correlated.', 'Risk & portfolio management', 'Basic', '{asset-allocation,correlation,portfolio,systematic-risk,unsystematic-risk}', '[]'::jsonb),
('sharpe-ratio', 'Sharpe ratio', 'A measure of risk-adjusted return — excess return per unit of total volatility.', 'Higher is better. Above 1 is considered good; above 2 excellent; above 3 exceptional. Useful for comparing strategies with different volatility profiles.', 'Risk & portfolio management', 'Intermediate', '{sortino-ratio,treynor-ratio,standard-deviation,alpha}', '[]'::jsonb),
('sortino-ratio', 'Sortino ratio', 'Like the Sharpe ratio but penalizes only downside volatility, not upside.', 'Argued to be more meaningful because investors don''t mind upside swings — only losses sting.', 'Risk & portfolio management', 'Advanced', '{sharpe-ratio,treynor-ratio,standard-deviation}', '[]'::jsonb),
('treynor-ratio', 'Treynor ratio', 'Excess return per unit of systematic (beta) risk rather than total volatility.', 'Useful for evaluating diversified portfolios where unsystematic risk has already been diversified away.', 'Risk & portfolio management', 'Advanced', '{sharpe-ratio,beta,systematic-risk}', '[]'::jsonb),
('value-at-risk', 'Value at risk (VaR)', 'An estimate of the maximum likely loss over a period at a given confidence level.', 'A 1-day 95% VaR of $1M means a 5% chance of losing more than $1M in a day. Widely used but criticized for hiding tail risk.', 'Risk & portfolio management', 'Advanced', '{expected-shortfall,standard-deviation,monte-carlo-simulation}', '[]'::jsonb),
('expected-shortfall', 'Expected shortfall', 'The average loss in the worst-case scenarios beyond the VaR threshold.', 'Also called Conditional VaR (CVaR). Captures tail risk more honestly than VaR alone.', 'Risk & portfolio management', 'Advanced', '{value-at-risk,monte-carlo-simulation}', '[]'::jsonb),
('beta', 'Beta', 'A stock''s sensitivity to broader market moves; the market itself has beta of 1.', 'Beta of 1.3 means the stock tends to move 30% more than the market — both up and down. Used in CAPM and risk-adjusted performance metrics.', 'Risk & portfolio management', 'Beginner', '{alpha,systematic-risk,treynor-ratio,sharpe-ratio}', '[{"title":"Reading beta","body":"A utility stock might have a beta near 0.5 (defensive), while a leveraged tech stock could be 2.0 (very cyclical)."}]'::jsonb),
('correlation', 'Correlation', 'A statistical measure of how two assets move in relation to each other, on a -1 to +1 scale.', 'Diversification works best when holdings have low or negative correlation. Correlations often rise toward 1 in crises, reducing diversification when it''s needed most.', 'Risk & portfolio management', 'Intermediate', '{covariance,diversification,modern-portfolio-theory}', '[]'::jsonb),
('covariance', 'Covariance', 'A measure of how two variables change together — positive when they move together, negative when opposite.', 'Used as a building block for correlation and portfolio variance calculations.', 'Risk & portfolio management', 'Advanced', '{correlation,standard-deviation,modern-portfolio-theory}', '[]'::jsonb),
('standard-deviation', 'Standard deviation', 'A measure of how much returns vary around their average — the classic measure of volatility.', 'Most modern risk and performance metrics, from VaR to Sharpe, are built on standard deviation.', 'Risk & portfolio management', 'Intermediate', '{sharpe-ratio,bollinger-bands,historical-volatility,value-at-risk}', '[]'::jsonb),
('systematic-risk', 'Systematic risk', 'Risk affecting the whole market that can''t be diversified away.', 'Driven by macro factors like interest rates, recessions, and policy. Captured by beta in CAPM.', 'Risk & portfolio management', 'Intermediate', '{unsystematic-risk,beta,diversification}', '[]'::jsonb),
('unsystematic-risk', 'Unsystematic risk', 'Risk specific to a single company or industry that can be diversified away.', 'Examples: a CEO scandal, a failed drug trial, a plant fire. Holding many uncorrelated securities effectively eliminates unsystematic risk.', 'Risk & portfolio management', 'Intermediate', '{systematic-risk,diversification,beta}', '[]'::jsonb),
('modern-portfolio-theory', 'Modern portfolio theory (MPT)', 'A framework for constructing portfolios that maximize expected return for a given level of risk.', 'Developed by Harry Markowitz in 1952. The efficient frontier emerges from this optimization.', 'Risk & portfolio management', 'Advanced', '{efficient-frontier,correlation,diversification}', '[]'::jsonb),
('efficient-frontier', 'Efficient frontier', 'The set of portfolios offering the highest expected return for each level of risk.', 'Any portfolio below the frontier is suboptimal — you could get more return for the same risk, or less risk for the same return.', 'Risk & portfolio management', 'Advanced', '{modern-portfolio-theory,sharpe-ratio,diversification}', '[]'::jsonb),
('monte-carlo-simulation', 'Monte Carlo simulation', 'A technique that runs thousands of randomized scenarios to model the range of possible outcomes.', 'Used in retirement planning, option pricing, and risk management — anywhere uncertainty makes a single-point forecast inadequate.', 'Risk & portfolio management', 'Advanced', '{value-at-risk,expected-shortfall}', '[]'::jsonb)

